-- ----------------------------
-- Table structure for `sys_wf_task`
-- ----------------------------
DROP TABLE IF EXISTS `sys_wf_task`;
CREATE TABLE `sys_wf_task` (
  `id` varchar(64) NOT NULL,
  `instance_id` varchar(64) NOT NULL,
  `node_id` varchar(64) NOT NULL,
  `node_name` varchar(200) DEFAULT NULL,
  `assignee` varchar(64) NOT NULL,
  `status` varchar(20) DEFAULT 'PENDING',
  `comment` varchar(1000) DEFAULT NULL,
  `is_add_sign` tinyint DEFAULT '0',
  `add_sign_pos` varchar(20) DEFAULT NULL,
  `create_time` datetime NOT NULL,
  `complete_time` datetime DEFAULT NULL,
  `is_from_reject` tinyint DEFAULT '0',
  `reject_reason` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_assignee_status` (`assignee`,`status`),
  KEY `idx_instance` (`instance_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------
-- 品牌外观 / Branding
-- 上游默认是 green 主题 + 一张指向已失效上传文件的 logo，
-- 这里改成品牌靛蓝 + 仓库自带的 logo.svg。
-- The upstream defaults are a green theme and a logo pointing at an upload that
-- no longer exists; use the brand indigo and the bundled logo instead.
-- ----------------------------
UPDATE `sys_configure` SET `configure_value` = 'custom'      WHERE `configure_key` = 'system.theme';
UPDATE `sys_configure` SET `configure_value` = '#4f46e5'     WHERE `configure_key` = 'system.theme.color';
UPDATE `sys_configure` SET `configure_value` = '/logo-mark.svg' WHERE `configure_key` = 'system.logo';
UPDATE `sys_configure` SET `configure_value` = '© 2026 GewuMind' WHERE `configure_key` = 'system.login.copyright';

-- ----------------------------
-- 清理上游遗留的测试数据 / drop leftover test data
-- 上游库里残留了 51 个 UT_TestApp_* 单元测试应用及对应授权，
-- 属于开发过程垃圾，新环境不应带上。
-- Upstream carried 51 UT_TestApp_* unit-test apps and their grants; that is
-- development debris and must not ship to a fresh environment.
-- ----------------------------
DELETE FROM `sys_open_app_api`;
DELETE FROM `sys_open_app`;
DELETE FROM `sys_open_app_request_log`;
DELETE FROM `sys_gen_info`;

-- ----------------------------
-- 菜单与授权 / Menus and grants
-- 「低代码」整个分组（低代码 / 代码生成 / 测试生成 / 动态组件 / 历史记录）已**物理删除**，
-- 连同其下 component:* / code:gen:* / data:test:* 权限码一并清除，不留软删残留与悬空授权引用。
-- 原「API管理」改为「在线编程」并挂到「系统设置」下，功能不受影响。
-- The whole 低代码 group (低代码 / 代码生成 / 测试生成 / 动态组件 / 历史记录) has been
-- physically removed, together with its component:* / code:gen:* / data:test:* permission
-- codes — no soft-deleted leftovers and no dangling grants. The former API管理 becomes
-- 在线编程, nested under 系统设置.
-- ----------------------------
-- Records of `sys_menu`
-- 授权关系只保留指向有效菜单的记录，不留悬空引用。
-- Grants only reference menus that still exist.
-- ----------------------------
INSERT INTO `sys_menu` VALUES ('0','','',NULL,'功能菜单','','',1,'0',0,NULL,NULL,NULL,NULL,1,1);
