-- 共 43 张表，734 行基础数据
-- ----------------------------
-- 脚本演示数据表 / Tables for the bundled script demos
-- 「脚本演示」分组下的示例脚本会查询 magic_api_info / magic_group，
-- 这两张表只服务于演示，不参与任何业务逻辑。
-- magic_api_info 与 magic_group back the bundled 脚本演示 examples only;
-- they are demo fixtures and carry no business meaning.
-- ----------------------------
DROP TABLE IF EXISTS `magic_api_info`;
DROP TABLE IF EXISTS `magic_group`;

CREATE TABLE `magic_group` (
  `id` varchar(32) NOT NULL,
  `group_name` varchar(100) NOT NULL,
  `parent_id` varchar(32) DEFAULT NULL,
  `create_date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='演示用分组表';

CREATE TABLE `magic_api_info` (
  `id` varchar(32) NOT NULL,
  `api_group_id` varchar(32) DEFAULT NULL,
  `api_name` varchar(100) NOT NULL,
  `api_path` varchar(200) DEFAULT NULL,
  `api_method` varchar(10) DEFAULT NULL,
  `api_status` tinyint DEFAULT 1,
  `description` varchar(255) DEFAULT NULL,
  `create_date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_group` (`api_group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='演示用接口信息表';

